import re
def loop_info(text):
    lns = text.split('\n')
    seen = {}
    for i,l in enumerate(lns):
        s = l.strip()
        if len(s) > 15:
            seen.setdefault(s, []).append(i)
    reps = {s:v for s,v in seen.items() if len(v) >= 5}
    if not reps: return None
    earliest = min(min(v) for v in reps.values())
    return earliest, len(reps)
