def build_amplify(token_id, alpha, writers='all'):
    for n in edited(): drop_edit(n)
    E = load_original('model.language_model.embed_tokens.weight').float()
    gamma = load_original('model.language_model.norm.weight').float()
    r = E[token_id]*(1+gamma)
    d = (r/r.norm()).numpy()
    dt = torch.from_numpy(d).float()
    targets = []
    for L in range(24):
        if writers in ('all','mlp'):
            targets.append(f'model.language_model.layers.{L}.mlp.down_proj.weight')
        if writers in ('all','attn'):
            if L in (3,7,11,15,19,23):
                targets.append(f'model.language_model.layers.{L}.self_attn.o_proj.weight')
            else:
                targets.append(f'model.language_model.layers.{L}.linear_attn.out_proj.weight')
    for name in targets:
        W = load_original(name).float()
        dW = dt @ W
        save_edit(name, W + alpha*torch.outer(dt, dW))
    return len(targets)

